class Logger {
 public:
  virtual ~Logger();
  virtual void log(LogSeverity severity,
                   const char * file,
                   int line,
                   const char * function,
                   const std::string & message) = 0;
};

class StdErrLogger
  : public Logger {
 public:
  void log(LogSeverity severity,
           const char * file,
           int line,
           const char * function,
           const std::string & message);
};

class FileLogger
  : public Logger {
 public:
  FileLogger(const char * logfile);
  void log(LogSeverity severity,
           const char * file,
           int line,
           const char * function,
           const std::string & message);
 protected:
