import random
import struct
import zlib
from typing import List

# We generate an arbitrary string buffer that is useful across many stubs:
# - Should often be valid UTF-8 text with tokens, numbers, punctuation
# - Sometimes should be binary-like with floats/uint32 for SIMD/math paths
# - Include patterns helpful for parsers (name=value, commas, spaces)
# - Bounded to 4096 bytes
# The fuzzer framework will slice/consume this buffer for FUZZ_PARAM_STR and
# also reinterpret segments as floats/ints in many stubs.

ASCII_WORDS = [
    "alpha", "beta", "gamma", "delta", "epsilon", "zeta", "eta", "theta",
    "lorem", "ipsum", "dolor", "sit", "amet", "param", "value", "key",
    "space", "method", "dist", "cosine", "angular", "lev", "sift", "id",
]

NUM_KEYS = ["k", "dim", "K", "threads", "qty", "max", "min", "hash", "p", "alpha", "beta"]
STR_KEYS = ["name", "file", "path", "space", "method", "externId", "label"]


def _pack_floats(vals: List[float]) -> bytes:
    return struct.pack('<' + 'f'*len(vals), *vals)


def _pack_u32(vals: List[int]) -> bytes:
    return struct.pack('<' + 'I'*len(vals), *[v & 0xFFFFFFFF for v in vals])


def _rand_float(rng: random.Random, lo=-10.0, hi=10.0) -> float:
    return rng.uniform(lo, hi)


def _rand_token(rng: random.Random) -> str:
    choice = rng.randrange(5)
    if choice == 0:
        # integer
        return str(rng.randrange(0, 100000))
    if choice == 1:
        # float with limited precision
        return f"{rng.uniform(-1000,1000):.4f}"
    if choice == 2:
        return rng.choice(ASCII_WORDS)
    if choice == 3:
        # simple base64-ish chunk
        alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
        return ''.join(rng.choice(alphabet) for _ in range(rng.randint(4, 16)))
    # short path-like
    segs = [rng.choice(ASCII_WORDS) for _ in range(rng.randint(1,3))]
    return "/".join(segs)


def _kv_pairs(rng: random.Random, n: int) -> str:
    parts = []
    used = set()
    for _ in range(n):
        if rng.random() < 0.5:
            k = rng.choice(NUM_KEYS)
            # ensure unique
            if k in used:
                k = f"{k}{rng.randrange(0,100)}"
            used.add(k)
            v = str(rng.randrange(0, 10000))
        else:
            k = rng.choice(STR_KEYS)
            if k in used:
                k = f"{k}{rng.randrange(0,100)}"
            used.add(k)
            v = _rand_token(rng)
        parts.append(f"{k}={v}")
    return ",".join(parts)


def _make_text_section(rng: random.Random, budget: int) -> bytes:
    lines = []
    # Header-like line
    lines.append(f"space={rng.choice(['l2','cosinesimil','angular','levenshtein'])},{_kv_pairs(rng, rng.randint(1,4))}")
    # Some name=value rows
    for _ in range(rng.randint(2,6)):
        lines.append(_kv_pairs(rng, rng.randint(1,5)))
    # Tokens splitters used by SplitStr/StartsWith/etc.
    tokens = [_rand_token(rng) for _ in range(rng.randint(5, 15))]
    sep = chr(rng.randrange(33, 96))  # printable non-space
    lines.append(sep.join(tokens))
    blob = ("\n".join(lines)).encode('utf-8', errors='ignore')
    if len(blob) > budget:
        blob = blob[:budget]
    return blob


def _make_float_blocks(rng: random.Random, blocks: int, each: int) -> bytes:
    out = bytearray()
    for _ in range(blocks):
        vals = []
        for _j in range(each):
            # Ensure mix of positive values for divergences and arbitrary for norms
            if rng.random() < 0.5:
                vals.append(abs(_rand_float(rng)) + 1e-3)
            else:
                vals.append(_rand_float(rng))
        out += _pack_floats(vals)
    return bytes(out)


def _make_u32_blocks(rng: random.Random, blocks: int, each: int) -> bytes:
    out = bytearray()
    for _ in range(blocks):
        vals = [rng.getrandbits(32) for _ in range(each)]
        out += _pack_u32(vals)
    return bytes(out)


def _make_sift_pair(rng: random.Random) -> bytes:
    # 128+128 bytes uint8 vectors
    v = bytes(rng.getrandbits(8) for _ in range(256))
    return v


def _with_label_prefix(rng: random.Random) -> bytes:
    # For Object::extractLabel expecting something like "label:<num> <rest>"
    lbl = rng.randrange(-1000, 1000)
    rest = _kv_pairs(rng, rng.randint(1,3))
    s = f"label:{lbl} {rest}\n"
    return s.encode('utf-8')


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Target size <= 4096 bytes
    budget = 4096
    chunks: List[bytes] = []

    # 1) Textual section for parsers and string utilities
    text_budget = rng.randint(400, 1200)
    chunks.append(_make_text_section(rng, text_budget))

    # 2) Label-prefixed line to sometimes allow successful extractLabel
    if rng.random() < 0.7:
        chunks.append(_with_label_prefix(rng))

    # 3) Float data blocks used by many math functions; provide two vectors back-to-back
    qty = rng.randint(1, 256)
    chunks.append(_make_float_blocks(rng, blocks=2, each=qty))

    # 4) Precomputed logs layout blocks for KL/JS/Itakura precomp: values then logs
    qty2 = rng.randint(1, 128)
    vals = [abs(_rand_float(rng)) + 1e-5 for _ in range(qty2)]
    # Normalize occasionally for JS/KL
    if rng.random() < 0.7:
        s = sum(vals)
        if s > 0:
            vals = [v/s for v in vals]
    logs = [float('nan') if v <= 0 else (0.0 if v == 1.0 else (0.0 + (v>0) and __import__('math').log(v))) for v in vals]
    # Replace NaNs (from guard) with safe logs
    import math
    logs = [math.log(v) if v > 0 else -1e5 for v in vals]
    chunks.append(_pack_floats(vals) + _pack_floats(logs))

    # 5) Bitset words for Jaccard/Hamming
    words = rng.randint(0, 64)
    chunks.append(_make_u32_blocks(rng, blocks=2, each=words))

    # 6) SIFT pair (256 bytes)
    chunks.append(_make_sift_pair(rng))

    # 7) Some compressed text to add entropy and binary variety
    extra_txt = " ".join(_rand_token(rng) for _ in range(rng.randint(20, 60))).encode('utf-8', errors='ignore')
    try:
        comp = zlib.compress(extra_txt)
        chunks.append(comp)
    except Exception:
        chunks.append(extra_txt)

    # 8) Append a small CSV-like and name=value trailing line
    tail = (",".join(_rand_token(rng) for _ in range(rng.randint(5,15))) + "\n" + _kv_pairs(rng, rng.randint(2,6)) + "\n").encode('utf-8')
    chunks.append(tail)

    # Concatenate within budget
    out = bytearray()
    for c in chunks:
        if len(out) + len(c) > budget:
            rem = budget - len(out)
            if rem <= 0:
                break
            out += c[:rem]
            break
        out += c

    # Ensure non-empty
    if not out:
        out.extend(b"x")

    return bytes(out)
